import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {colors,symbols,radii,orbitalCloud} from './chemistry.js';
export class Studio{
 constructor(host,onPick){
  this.host=host;this.scene=new THREE.Scene();this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.setClearColor(0,0);this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.3;host.append(this.renderer.domElement);
  this.camera=new THREE.PerspectiveCamera(38,1,.1,200);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=true;this.controls.minDistance=3;this.controls.maxDistance=65;this.controls.autoRotateSpeed=.7;
  this.scene.add(new THREE.HemisphereLight(0xe9f9ff,0x677b84,2.6));const key=new THREE.DirectionalLight(0xffffff,3.3);key.position.set(5,8,7);this.scene.add(key);const fill=new THREE.DirectionalLight(0x94c5de,2.4);fill.position.set(-6,0,-4);this.scene.add(fill);
  this.root=new THREE.Group();this.scene.add(this.root);this.tick=()=>{};this.duration=0;this.active=true;this.bounds=8;
  this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(host);this.reset();
  const ray=new THREE.Raycaster();let down=null;host.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);host.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=host.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),this.camera);const obj=ray.intersectObjects(this.root.children,true).find(h=>h.object.userData.label);onPick(obj?.object.userData.label||'');});
  this.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();this.active=false;onPick('Grafikkontext verloren. Bitte die Seite neu laden.');});
  let previous=performance.now();this.renderer.setAnimationLoop(now=>{let dt=Math.min((now-previous)/1000,.05);previous=now;if(document.hidden||!this.active)return;this.duration+=dt;this.tick(this.duration,dt);this.controls.update();this.renderer.render(this.scene,this.camera);});
 }
 resize(){const w=this.host.clientWidth,h=this.host.clientHeight;if(!w||!h)return;this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.renderer.setSize(w,h);}
 reset(){this.controls.target.set(0,0,0);const aspect=this.host.clientWidth/Math.max(this.host.clientHeight,1);const d=this.bounds/Math.min(1,aspect);this.camera.position.set(d*.25,d*.2,d*1.6);this.controls.update();}
 clear(){this.tick=()=>{};this.root.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of(Array.isArray(o.material)?o.material:[o.material])){m.map?.dispose();m.dispose();}}});this.root.clear();this.root.rotation.set(0,0,0);}
 ball(parent,xyz,r,color,label='',opacity=1){const mat=new THREE.MeshStandardMaterial({color,roughness:.29,metalness:.08,transparent:opacity<1,opacity,depthWrite:opacity>=1});const mesh=new THREE.Mesh(new THREE.SphereGeometry(r,28,18),mat);mesh.position.set(...xyz);mesh.userData.label=label;parent.add(mesh);return mesh;}
 stick(parent,a,b,color='#849a9d',radius=.085,opacity=1){a=new THREE.Vector3(...a);b=new THREE.Vector3(...b);const diff=b.clone().sub(a);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,diff.length(),12),new THREE.MeshStandardMaterial({color,roughness:.5,transparent:opacity<1,opacity}));mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),diff.normalize());parent.add(mesh);return mesh;}
 label(parent,text,xyz,color='#27474d'){const c=document.createElement('canvas');c.width=256;c.height=96;const ctx=c.getContext('2d');ctx.fillStyle='#f8fcfaee';ctx.beginPath();ctx.roundRect(10,12,236,72,18);ctx.fill();ctx.fillStyle=color;ctx.font='500 42px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,128,49);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,depthTest:false}));sp.scale.set(1.65,.62,1);sp.position.set(...xyz);parent.add(sp);return sp;}
 ring(parent,r,color='#91b0ad'){const pts=[];for(let i=0;i<=128;i++){let a=i/128*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(a)*r,0,Math.sin(a)*r));}const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color,transparent:true,opacity:.5}));parent.add(line);return line;}
 atom(el,mode,n=1,l=0,m=0){this.clear();this.bounds=mode==='orbital'?8:Math.max(4.5,(1.65+(el.shells.length-1)*.66)*1.8);
  if(mode==='orbital'){const cloud=orbitalCloud(n,l,m);const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(cloud.positions,3));const cs=[];const pos=new THREE.Color('#249d98'),neg=new THREE.Color('#b28be0');cloud.phases.forEach(p=>{const c=p>0?pos:neg;cs.push(c.r,c.g,c.b);});geo.setAttribute('color',new THREE.Float32BufferAttribute(cs,3));this.root.add(new THREE.Points(geo,new THREE.PointsMaterial({size:.062,vertexColors:true,transparent:true,opacity:.78,depthWrite:false,toneMapped:false})));this.ball(this.root,[0,0,0],.13,'#ccac6f','Kern (symbolisch)');this.reset();return;}
  const nucleus=new THREE.Group();this.root.add(nucleus);const count=Math.min(el.z,32);for(let i=0;i<count;i++){const y=1-2*(i+.5)/count,a=i*2.39996,r=.25+.35*Math.cbrt(count/32);this.ball(nucleus,[Math.sqrt(1-y*y)*Math.cos(a)*r,y*r,Math.sqrt(1-y*y)*Math.sin(a)*r],.19,i%2?'#ddad7c':'#587a91','Kern: '+el.z+' Protonen; Nukleonen nur symbolisch');}
  const electrons=[];el.shells.forEach((count,s)=>{let r=1.65+s*.66;const group=new THREE.Group();group.rotation.x=.2+s*.24;group.rotation.z=s*.18;this.root.add(group);this.ring(group,r);for(let j=0;j<count;j++){const ball=this.ball(group,[0,0,0],.09,'#238878',`Elektron · Schale ${s+1}`);electrons.push({ball,r,angle:j/count*Math.PI*2,s});}});
  const update=t=>electrons.forEach(e=>{const a=e.angle+t*.16/(e.s+1);e.ball.position.set(Math.cos(a)*e.r,0,Math.sin(a)*e.r)});update(0);this.tick=t=>update(matchMedia('(prefers-reduced-motion: reduce)').matches?0:t);this.reset();
 }
 lattice(parent,size=4){const ions=[];for(let x=0;x<size;x++)for(let y=0;y<size;y++)for(let z=0;z<size;z++){let na=(x+y+z)%2===0;let xyz=[x,y,z].map(v=>(v-(size-1)/2)*1.3);let ball=this.ball(parent,xyz,na?.31:.46,colors[na?11:17],na?'Na⁺ · Natriumion':'Cl⁻ · Chloridion');ions.push({ball,na,start:new THREE.Vector3(...xyz)});for(const d of[[1,0,0],[0,1,0],[0,0,1]])if(x+d[0]<size&&y+d[1]<size&&z+d[2]<size)this.stick(parent,xyz,xyz.map((v,i)=>v+d[i]*1.3),'#96b5af',.025,.28);}return ions;}
 molecule(data,style='ball',hydrogen=true){this.clear();if(data.kind==='lattice'){this.lattice(this.root);this.bounds=7;this.reset();return;}
  const center=[0,0,0];data.atoms.forEach(a=>a.xyz.forEach((v,i)=>center[i]+=v/data.atoms.length));const positions=data.atoms.map(a=>a.xyz.map((v,i)=>v-center[i]));let max=0;data.atoms.forEach((a,i)=>{if(!hydrogen&&a.element===1)return;max=Math.max(max,Math.hypot(...positions[i]));this.ball(this.root,positions[i],style==='space'?(radii[a.element]||1.7):a.element===1?.23:.4,colors[a.element]||'#b5b5bd',`${symbols[a.element]||a.element} · Atom ${i+1}`);});
  if(style==='ball')data.bonds.forEach(([a,b,order])=>{if(!hydrogen&&(data.atoms[a].element===1||data.atoms[b].element===1))return;const p=new THREE.Vector3(...positions[a]),q=new THREE.Vector3(...positions[b]);let normal=new THREE.Vector3().crossVectors(q.clone().sub(p),new THREE.Vector3(0,1,0));if(normal.length()<.01)normal.crossVectors(q.clone().sub(p),new THREE.Vector3(1,0,0));normal.normalize();for(let j=0;j<Math.min(order,3);j++){const off=normal.clone().multiplyScalar((j-(Math.min(order,3)-1)/2)*.17);const aa=p.clone().add(off),bb=q.clone().add(off),mid=aa.clone().add(bb).multiplyScalar(.5);this.stick(this.root,aa.toArray(),mid.toArray(),colors[data.atoms[a].element]);this.stick(this.root,mid.toArray(),bb.toArray(),colors[data.atoms[b].element]);}});this.bounds=Math.max(6,max*1.9);this.reset();
 }
 water(parent,position,ionPositive,ionCenter){const g=new THREE.Group();parent.add(g);g.position.copy(position);this.ball(g,[0,0,0],.21,colors[8],'O · negative Partialladung δ−');const angle=104.5/2*Math.PI/180;for(const s of[-1,1]){const p=[s*Math.sin(angle)*.42,Math.cos(angle)*.42,0];this.ball(g,p,.115,colors[1],'H · positive Partialladung δ+');this.stick(g,[0,0,0],p,'#becdcd',.047);}let away=position.clone().sub(ionCenter).normalize();g.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),ionPositive?away:away.negate());return g;}
 process(id){this.clear();this.bounds=8;let update;
  if(id==='ionic'){
   const atom=new THREE.Group();this.root.add(atom);const na=this.ball(atom,[-2.3,0,0],.63,colors[11],'Natrium');const cl=this.ball(atom,[2.3,0,0],.83,colors[17],'Chlor');this.ring(atom,0);const electron=this.ball(atom,[-3.4,0,0],.11,'#218e9a','Übertragenes Elektron');const left=this.label(atom,'Na',[-2.3,-1.6,0]),right=this.label(atom,'Cl',[2.3,-1.6,0]);const charged=new THREE.Group();this.root.add(charged);this.label(charged,'Na⁺',[-2.3,-1.6,0]);this.label(charged,'Cl⁻',[2.3,-1.6,0]);const lattice=new THREE.Group();this.root.add(lattice);this.lattice(lattice);
   // Valence electrons before transfer: one for Na, seven for Cl; eighth is the moving electron.
   const val=[];for(let j=0;j<7;j++){let a=j/8*Math.PI*2;val.push(this.ball(atom,[2.3+Math.cos(a)*1.16,Math.sin(a)*1.16,0],.085,'#218e9a','Chlor: Außenelektron'));}
   update=p=>{let t=THREE.MathUtils.smoothstep(p,.25,.5);atom.visible=p<.75;charged.visible=p>=.5&&p<.75;left.visible=right.visible=p<.5;lattice.visible=p>=.75;electron.position.set(THREE.MathUtils.lerp(-3.4,2.3+Math.cos(7/8*Math.PI*2)*1.16,t),Math.sin(7/8*Math.PI*2)*1.16*t+Math.sin(t*Math.PI)*1.5,0);na.scale.setScalar(p>=.5?.8:1);cl.scale.setScalar(p>=.5?1.1:1);};
  }else if(id==='covalent'){
   const left=new THREE.Group(),right=new THREE.Group();this.root.add(left,right);this.ball(left,[0,0,0],.24,'#ccad7a','Proton');this.ball(right,[0,0,0],.24,'#ccad7a','Proton');this.ball(left,[0,0,0],1.05,'#62a8b5','1s-Aufenthaltsraum (schematisch)',.14);this.ball(right,[0,0,0],1.05,'#62a8b5','1s-Aufenthaltsraum (schematisch)',.14);const pair=[this.ball(this.root,[0,0,0],.1,'#298d90','Elektron im gemeinsamen Paar'),this.ball(this.root,[0,0,0],.1,'#298d90','Elektron im gemeinsamen Paar')];this.label(left,'H',[0,-1.7,0]);this.label(right,'H',[0,-1.7,0]);const bond=this.ball(this.root,[0,0,0],1,'#39a58f','Bindungsraum (schematisch)',.15);bond.scale.set(1.3,.6,.6);
   update=p=>{const t=THREE.MathUtils.smoothstep(p,.1,.75),d=THREE.MathUtils.lerp(2.6,.65,t);left.position.x=-d;right.position.x=d;pair[0].position.set(THREE.MathUtils.lerp(-d,.0,t),.28,0);pair[1].position.set(THREE.MathUtils.lerp(d,.0,t),-.28,0);bond.visible=p>.48;};
  }else{
   const lattice=new THREE.Group();this.root.add(lattice);const ions=this.lattice(lattice,2);const waters=[];
   ions.forEach((ion,j)=>{ion.end=ion.start.clone().normalize().multiplyScalar(3.2);for(let k=0;k<3;k++){const a=k/3*Math.PI*2+j*.4;const offset=new THREE.Vector3(Math.cos(a)*.9,Math.sin(a)*.9,(k-1)*.28);const g=this.water(this.root,ion.end.clone().add(offset),ion.na,ion.end);waters.push({g,ion,offset,random:new THREE.Quaternion().setFromEuler(new THREE.Euler(k+.6,j+.3,1)),aligned:g.quaternion.clone()});}});
   update=p=>{const t=THREE.MathUtils.smoothstep(p,.35,.85);ions.forEach(ion=>ion.ball.position.copy(ion.start).lerp(ion.end,t));lattice.children.filter(o=>o.geometry?.type==='CylinderGeometry').forEach(o=>o.visible=p<.45);waters.forEach(({g,ion,offset,random,aligned},j)=>{g.position.copy(ion.ball.position).add(offset.clone().multiplyScalar(THREE.MathUtils.lerp(1.8,1,THREE.MathUtils.smoothstep(p,0,.4))));g.quaternion.copy(random).slerp(aligned,THREE.MathUtils.smoothstep(p,.12,.4));});};
  }
  update(0);this.reset();return update;
 }
 export(title){this.renderer.render(this.scene,this.camera);const c=document.createElement('canvas');const src=this.renderer.domElement;c.width=src.width;c.height=src.height+100;const ctx=c.getContext('2d');ctx.fillStyle='#edf3f3';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(src,0,0);ctx.fillStyle='#20483f';ctx.font='bold 25px sans-serif';ctx.fillText('ELEMENTA · '+title,24,c.height-60);ctx.font=Math.min(15,(c.width-48)/80)+'px sans-serif';ctx.fillText('DGKN@Labs · Lernmodell · Quellen: OpenStax Chemistry 2e / PubChem',24,c.height-28);c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ELEMENTA-'+title.replace(/[^a-zA-Z0-9äöüÄÖÜß-]/g,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);});}
}
